var EX_FOTOS_ALIASES={"agachamento no smith": "data:image/jpeg;base64,", "leg press 45": "data:image/jpeg;base64,", "stiff / terra romeno": "data:image/jpeg;base64,", "cadeira extensora": "data:image/jpeg;base64,", "cadeira flexora": "data:image/jpeg;base64,", "panturrilha em pe": "data:image/jpeg;base64,", "panturrilha sentado": "data:image/jpeg;base64,", "adutora": "data:image/jpeg;base64,", "abdutora": "data:image/jpeg;base64,", "supino reto": "data:image/jpeg;base64,", "supino inclinado c/ halteres": "data:image/jpeg;base64,", "voador": "data:image/jpeg;base64,", "elevacao lateral": "data:image/jpeg;base64,", "triceps na polia": "data:image/jpeg;base64,", "triceps frances na polia": "data:image/jpeg;base64,", "abdominal na polia": "data:image/jpeg;base64,", "puxada aberta": "data:image/jpeg;base64,", "remada baixa": "data:image/jpeg;base64,", "serrote (remada unilateral)": "data:image/jpeg;base64,", "crucifixo inverso": "data:image/jpeg;base64,", "rosca na polia": "data:image/jpeg;base64,", "rosca banco 45° c/ halteres": "data:image/jpeg;base64,"};
function canonKey(name){
  var s=exerciseNameKey(name);
  s=s.replace(/°/g,'').replace(/\s+/g,' ').trim();
  if(EX_FOTOS_ALIASES[s]) return s;
  var keys=Object.keys(EX_FOTOS_ALIASES);
  for(var i=0;i<keys.length;i++){ var k=keys[i];
    if(s.indexOf(k)===0 || k.indexOf(s)===0) return k;
    var s2=s.replace(/°/g,''), k2=k.replace(/°/g,'');
    if(s2===k2 || s2.indexOf(k2)===0 || k2.indexOf(s2)===0) return k;
  }
  return s;
}
